code.cpp:
class Solution {
public:
    int minimumCost(vector<int>& nums) {
        int n = nums.size();
        int first = INT_MAX, second = INT_MAX;
        for (int i = 1; i < n; i++) {
            if (nums[i] < first) {
                second = first;
                first = nums[i];
            } else if (nums[i] < second) {
                second = nums[i];
            }
        }
        return nums[0] + first + second;
    }
};
